315	    @Override
316	    @Transactional(readOnly = true)
317	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
318	        return !findHouseholdMembers(owner).isEmpty();
319	    }
320	
321	    @Override
322	    @Transactional(readOnly = true)
323	    public Collection<Owner> findHouseholdMembers(Owner owner) throws DataAccessException {
324	        String householdId = owner.getHouseholdId();
325	        if (householdId == null) {
326	            return List.of();
327	        }
328	        return ownerRepository.findAll().stream()
329	            .filter(existing -> existing.getId() != null)
330	            .filter(existing -> !existing.isDeleted())
331	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
332	            .collect(Collectors.toList());
333	    }
334	
335	    /**
336	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
337	     * whitespace to a single space and lower-case the result, so values that differ only in
338	     * letter case or incidental whitespace are treated as equal. Shared by the household
339	     * (last name) and per-city matching rules.
340	     */
341	    private String normalizeForComparison(String value) {
342	        if (value == null) {
343	            return null;
344	        }
345	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
346	    }
347	
348	    @Override
349	    @Transactional(readOnly = true)
350	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
351	        String identityKey = owner.getIdentityKey();
352	        return ownerRepository.findAll().stream()
353	            .filter(existing -> !existing.isDeleted())
354	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
355	    }
356	
357	    @Override
358	    @Transactional(readOnly = true)
359	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
360	        String normalizedLastName = normalizeForComparison(owner.getLastName());
361	        String postcode = owner.getPostcode();
362	        if (normalizedLastName == null || postcode == null) {
363	            return null;
364	        }
365	        String telephone = owner.getTelephone();
366	        return ownerRepository.findAll().stream()
367	            .filter(existing -> existing.getId() != null)
368	            .filter(existing -> !existing.isDeleted())
369	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName())))
370	            .filter(existing -> postcode.equals(existing.getPostcode()))
371	            .filter(existing -> telephone == null
372	                ? existing.getTelephone() != null
373	                : !telephone.equals(existing.getTelephone()))
374	            .map(Owner::getId)
375	            .min(Integer::compareTo)
376	            .orElse(null);
377	    }
378	
379	    @Override
380	    @Transactional(readOnly = true)
381	    public int countNamesakes(String firstName, String lastName) throws DataAccessException {
382	        if (firstName == null || lastName == null) {
383	            return 0;
384	        }
385	        return (int) ownerRepository.findAll().stream()
386	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
387	                && lastName.equalsIgnoreCase(existing.getLastName()))
388	            .count();
389	    }
390	
391	    @Override
392	    @Transactional(readOnly = true)
393	    public int countOwnersInCity(String city) throws DataAccessException {
394	        String normalized = normalizeForComparison(city);
395	        if (normalized == null) {
396	            return 0;
397	        }
398	        return (int) ownerRepository.findAll().stream()
399	            .filter(existing -> normalized.equals(normalizeForComparison(existing.getCity())))
400	            .count();
401	    }
402	
403	    @Override
404	    @Transactional(readOnly = true)
405	    public int countOwnersRegisteredOn(LocalDate date) throws DataAccessException {
406	        if (date == null) {
407	            return 0;
408	        }
409	        return (int) ownerRepository.findAll().stream()
410	            .filter(existing -> date.equals(existing.getRegistrationDate()))
411	            .count();
412	    }
413	
414	    @Override
415	    @Transactional(readOnly = true)
416	    public Collection<Visit> findVisitsByPetId(int petId) {
417	        return visitRepository.findByPetId(petId);
418	    }
419	
420	    @Override
421	    @Transactional(readOnly = true)
422	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
423	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
424	    }
425	
426	    private <T> T findEntityById(Supplier<T> supplier) {
427	        try {
428	            return supplier.get();
429	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
430	            // Just ignore not found exceptions for Jdbc/Jpa realization
431	            return null;
432	        }
433	    }
434	
435	}
