17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.service.IdempotencyStore;
44	import org.springframework.samples.petclinic.util.BusinessDays;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.servlet.http.HttpServletRequest;
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
64	     * customerCode and registrationDate. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
68	    private static final int CITY_CAPACITY = 50;
69	
70	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
71	     * create is rejected once this many owners already carry today's registration date. */
72	    private static final int DAILY_REGISTRATION_LIMIT = 100;
73	
74	    /** Once more than this many owners already carry a given day's registration date, a new owner
75	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** HTTP header carrying the client-supplied idempotency key for a create. */
79	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final HttpServletRequest request;
90	
91	    private final IdempotencyStore idempotencyStore;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 HttpServletRequest request,
98	                                 IdempotencyStore idempotencyStore) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.request = request;
104	        this.idempotencyStore = idempotencyStore;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
136	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
137	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
138	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
139	        if (hasIdempotencyKey) {
140	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
141	                .map(this.clinicService::findOwnerById);
142	            if (existing.isPresent()) {
143	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
144	            }
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        // The effective registration date (supplied, or the server date when omitted) must fall on
149	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
150	        // registration date — the stored value, the per-day limit below and the membership number —
151	        // uses this adjusted date.
152	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
153	        owner.setRegistrationDate(effectiveDate);
154	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
155	        // further creates for that day with 429 Too Many Requests.
156	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
157	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
158	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
159	        }
160	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
161	        // for its registration date, signalling a bulk-signup surge.
162	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
163	        // Per-city capacity: a city that already holds the maximum number of owners is full.
164	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        // The household id is derived deterministically on the owner itself (see
168	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
169	        // last name and postcode share it automatically — no linking step and no ordering to manage.
170	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
172	        // (normalized telephone | email-or-empty | householdId) equals an existing owner's. A
173	        // truly identical record is always rejected, independent of sharesHousehold.
174	        if (this.clinicService.isIdentityKeyInUse(owner)) {
175	            return new ResponseEntity<>(HttpStatus.CONFLICT);
176	        }
177	        // Household membership: another owner may already belong to this (last name, postcode)
178	        // household. A new member is admitted rather than rejected — its membership level is instead
179	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
180	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
181	        // possible duplicate for review.
182	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
183	        // Soft "possible duplicate" detection: an existing owner shares this owner's last name and
184	        // postcode with a different telephone. A declared household member (sharesHousehold on an
185	        // in-use household) is an intentional share, not a suspected duplicate, so it is not
186	        // flagged; otherwise the create still proceeds, flagged with possibleDuplicate=true and
187	        // possibleDuplicateOf set to the matching owner id.
188	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
189	            ? null
190	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
191	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
192	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
193	        owner.setNamesakeCount(
194	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
195	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
196	        // current maximum level among its existing household members. Derive the cap from those
197	        // members' effective (already-capped) levels; with no existing member the cap stays null
198	        // and the owner's level is used uncapped.
199	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
200	        if (!householdMembers.isEmpty()) {
201	            int maxHouseholdLevel = householdMembers.stream()
202	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
203	                .max()
204	                .getAsInt();
205	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
206	        }
207	        this.clinicService.saveOwner(owner);
208	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
209	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
210	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
211	        if (hasIdempotencyKey) {
212	            this.idempotencyStore.record(idempotencyKey, owner.getId());
213	        }
214	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
215	        headers.setLocation(UriComponentsBuilder.newInstance()
216	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
217	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
228	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
229	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
230	        currentOwner.setCity(ownerFieldsDto.getCity());
231	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
232	        currentOwner.setLastName(ownerFieldsDto.getLastName());
233	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
234	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
235	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
236	        this.clinicService.saveOwner(currentOwner);
237	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Transactional
242	    @Override
243	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
244	        Owner owner = this.clinicService.findOwnerById(ownerId);
245	        if (owner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        this.clinicService.deleteOwner(owner);
249	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
250	    }
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
255	        Owner owner = this.clinicService.findOwnerById(ownerId);
256	        if (owner == null) {
257	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	        }
259	        HttpHeaders headers = new HttpHeaders();
260	        Pet pet = petMapper.toPet(petFieldsDto);
261	        owner.setId(ownerId);
262	        pet.setOwner(owner);
263	        pet.getType().setName(null);
264	        this.clinicService.savePet(pet);
265	        PetDto petDto = petMapper.toPetDto(pet);
266	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
267	            .buildAndExpand(pet.getId()).toUri());
268	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
274	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
275	        if (currentOwner != null) {
276	            Pet currentPet = this.clinicService.findPetById(petId);
277	            if (currentPet != null) {
278	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
279	                currentPet.setName(petFieldsDto.getName());
280	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
281	                this.clinicService.savePet(currentPet);
282	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
283	            }
284	        }
285	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
291	        HttpHeaders headers = new HttpHeaders();
292	        Visit visit = visitMapper.toVisit(visitFieldsDto);
293	        Pet pet = new Pet();
294	        pet.setId(petId);
295	        visit.setPet(pet);
296	        this.clinicService.saveVisit(visit);
297	        VisitDto visitDto = visitMapper.toVisitDto(visit);
298	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
299	            .buildAndExpand(visit.getId()).toUri());
300	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
301	    }
302	
303	
304	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
305	    @Override
306	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
307	        Owner owner = this.clinicService.findOwnerById(ownerId);
308	        if (owner != null) {
309	            Pet pet = owner.getPet(petId);
310	            if (pet != null) {
311	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
312	            }
313	        }
314	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
315	    }
316	}
