421	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
422	        ownerPageDto.setPage(ownerPage.getNumber());
423	        ownerPageDto.setSize(ownerPage.getSize());
424	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
425	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
426	        return ownerPageDto;
